"""Actual HyperFrames HTML/GSAP authoring: source media + HUD + phrase captions."""
from pathlib import Path
import json,math,html,shutil
R=Path(__file__).resolve().parents[1];H=R/'hyperframes';D=R/'hyperframes-demo'
CSS="""@font-face{font-family:FilmSans;src:url('assets/FilmSans-Bold.ttf');font-weight:700}@font-face{font-family:FilmSans;src:url('assets/FilmSans-Regular.ttf');font-weight:400}*{box-sizing:border-box}#root{position:absolute;inset:0;font-family:FilmSans;color:#f5f3ed}.clip{position:absolute;inset:0;pointer-events:none}.panel{position:absolute;background:rgba(5,17,29,.91);border:1.5px solid #e89b48;border-radius:14px;padding:24px;box-shadow:0 10px 24px rgba(0,0,0,.2)}.label{font-size:28px;font-weight:700;line-height:1.25;letter-spacing:2px;color:#d3dadd}.value{font-size:80px;font-weight:700;line-height:1.1;letter-spacing:-2px;font-variant-numeric:tabular-nums}.unit{font-size:28px;line-height:1.2;letter-spacing:0;color:#d6dadd}.track{position:absolute;left:24px;right:24px;bottom:21px;height:7px;background:#344652;border-radius:3px;overflow:hidden}.fill{height:100%;background:#f7a34c;transform-origin:left center}.gauge .value{position:absolute;left:24px;top:69px}.gauge .unit{position:absolute;right:24px;top:114px}.gauge svg{position:absolute;left:35px;top:132px;width:340px;height:239px}.clock .value{font-size:56px;margin-top:10px;letter-spacing:-1px}.clock .unit{position:absolute;right:24px;bottom:26px}.compact .value{margin-top:8px}.compact .unit{position:absolute;right:24px;top:100px}.caption{position:absolute;left:108px;top:1610px;width:864px;text-align:center;font-size:52px;font-weight:700;line-height:1.25;letter-spacing:-1px}.caption-body{display:inline-block;background:rgba(4,14,24,.91);padding:10px 18px 14px;border-radius:9px}.caption-word{display:inline-block}.emphasis{color:#ffb15b}.rule{position:absolute;height:3px;background:#f4a14b;left:24px;right:24px;top:0;transform-origin:left center}.demo-title{position:absolute;left:108px;top:190px;font-size:38px;font-weight:700;letter-spacing:1px} .caption em{font-style:normal;color:#ffb15b}"""
def dial(id,maxi):
 out='<svg viewBox="0 0 340 260" aria-label="calibrated instrument">'
 for j in range(29):
  th=math.radians(140+260*j/28);major=j%7==0;ro=110;ri=96 if major else 104
  out+=f'<path d="M{170+ro*math.cos(th):.3f} {144+ro*math.sin(th):.3f} L{170+ri*math.cos(th):.3f} {144+ri*math.sin(th):.3f}" stroke="'+('#f6a64f' if j>23 else '#b9cbd1')+f'" stroke-width="{3 if major else 1.5}"/>'
 for j,val in [(0,0),(14,maxi/2),(28,maxi)]:
  th=math.radians(140+260*j/28);out+=f'<text x="{170+120*math.cos(th):.2f}" y="{152+120*math.sin(th):.2f}" fill="#d4dce0" font-size="32" font-family="FilmSans" text-anchor="middle">{val:g}</text>'
 out+=f'<g id="{id}"><circle cx="170" cy="144" r="110" fill="transparent"/><path d="M151 144 L269 144" stroke="#ffb15b" stroke-width="5" stroke-linecap="round"/></g><circle cx="170" cy="144" r="8" fill="#f2d1a0"/></svg>'
 return out

def gauge(id,label,x,y,maximum,unit):
 return f'<section id="{id}-panel" class="panel gauge" style="left:{x}px;top:{y}px;width:410px;height:410px"><div id="{id}-rule" class="rule"></div><div class="label">{label}</div><div id="{id}-value" class="value">0</div><div class="unit">{unit}</div>{dial(id+"-needle",maximum)}<div class="track"><div id="{id}-bar" class="fill"></div></div></section>'

def clip(id,start,end,inside):return f'<div id="{id}" class="clip" data-start="{start}" data-duration="{end-start}">{inside}</div>'
def template(id,body,js):return f'<template><style>{CSS}</style><div id="root" data-composition-id="{id}" data-width="1080" data-height="1920">{body}</div><script>{js}</script></template>'
clock='<section id="clock-panel" class="panel clock" style="left:108px;top:230px;width:394px;height:168px"><div id="clock-rule" class="rule"></div><div class="label">LOCAL TIME</div><div id="clock-value" class="value">02:17:00</div><div class="unit">AM</div></section>'
body=clip('time-clip',0,2,clock)
body+=clip('instruments-clip',4.05,9,gauge('speed','VEHICLE SPEED',108,230,140,'km/h')+gauge('rpm','ENGINE RPM',548,230,8,'×1000'))
body+=clip('pursuit-clip',9,11.7,'<section id="gap-panel" class="panel compact" style="left:108px;top:230px;width:394px;height:204px"><div id="gap-rule" class="rule"></div><div class="label">PURSUER GAP</div><div id="gap-value" class="value">0</div><div class="unit">m</div><div class="track"><div id="gap-bar" class="fill"></div></div></section>')
js="""(()=>{const C=HFComponents,V=V4Components,tl=gsap.timeline({paused:true});const clock=new C.DigitalClock('#clock-value'),speed=new C.SpeedometerOverlay({value:'#speed-value',needle:'#speed-needle',bar:'#speed-bar'}),rpm=new V.TachometerOverlay('#rpm-value','#rpm-needle','#rpm-bar'),gap=new C.PursuitDistanceHUD('#gap-value','#gap-bar');[['clock',.04,2],['speed',4.05,9],['rpm',4.11,9],['gap',9,11.7]].forEach(([id,s,e])=>{new C.CinematicHUDPanel('#'+id+'-panel').animate(tl,s,e);new V.AnimatedTransition('#'+id+'-rule').animate(tl,s,e);});function draw(t){const s=C.vehicleAt(t);clock.render(t);speed.render(s);rpm.render(s);gap.render(s);}const p={t:0};tl.to(p,{t:15,duration:15,ease:'none',onUpdate:()=>draw(p.t)},0);window.addEventListener('hf-seek',e=>draw(e.detail.time));draw(0);window.__timelines=window.__timelines||{};window.__timelines.hud=tl;})();"""
(H/'compositions/hud.html').write_text(template('hud',body,js))
# Preserve V3 speech; animate full measured phrases, not unverified guessed word boundaries.
caps=json.loads((R/'caption-timing.json').read_text());body='';js='const tl=gsap.timeline({paused:true});'
for j,c in enumerate(caps):
 # Keep pedal action unobscured: all captions live in the safe lower band.
 words=c['text'].split();inner=' '.join(f'<span id="cap-{j}-w-{k}" class="caption-word '+('emphasis' if w.lower().strip('.,') in ['gas','followed','behind'] else '')+'">'+html.escape(w)+'</span>' for k,w in enumerate(words))
 body+=clip(f'caption-{j}-clip',c['start'],c['end'],f'<div id="cap-{j}" class="caption" data-layout-allow-caption-zone><span class="caption-body">{inner}</span></div>')
 js+=f"new V4Components.WordByWordCaptions('#cap-{j}').phrase(tl,{c['start']},{c['end']});"
js+="window.__timelines=window.__timelines||{};window.__timelines.captions=tl;"
(H/'compositions/captions.html').write_text(template('captions',body,'(()=>{'+js+'})();'))
HEAD='''<!doctype html><html lang="en"><head><meta charset="UTF-8"><script src="assets/gsap.min.js"></script><script src="assets/vehicle-state.js"></script><script src="assets/components.js"></script><script src="assets/components-v4.js"></script><style>html,body{margin:0;width:1080px;height:1920px;overflow:hidden;background:#06131e}*{box-sizing:border-box}#root{position:absolute;inset:0}</style></head><body>'''
root=HEAD+'''<div id="root" data-composition-id="main" data-start="0" data-duration="15" data-width="1080" data-height="1920" data-fps="30"><video id="scene-layer" class="clip" data-start="0" data-duration="15" data-track-index="0" src="assets/animation-base-v4b-hd.mp4" muted playsinline style="position:absolute;inset:0;width:1080px;height:1920px;object-fit:contain;z-index:0" data-layout-ignore></video><audio id="sound-mix" class="clip" data-start="0" data-duration="15" data-track-index="1" src="assets/mix.wav" data-volume="1"></audio><div id="hud" class="clip" data-composition-id="hud" data-composition-src="compositions/hud.html" data-start="0" data-duration="15" data-track-index="2" data-track-kind="graphics" data-width="1080" data-height="1920" style="z-index:2"></div><div id="captions" class="clip" data-composition-id="captions" data-composition-src="compositions/captions.html" data-start="0" data-duration="15" data-track-index="3" data-track-kind="captions" data-width="1080" data-height="1920" style="z-index:3"></div></div><script>const tl=gsap.timeline({paused:true});tl.to({t:0},{t:15,duration:15,ease:'none'},0);window.__timelines=window.__timelines||{};window.__timelines.main=tl;</script></body></html>'''
(H/'index.html').write_text(root)
demo=HEAD+f'<style>{CSS}</style><div id="root" data-composition-id="demo" data-start="0" data-duration="6" data-width="1080" data-height="1920" data-fps="30">'
demo+=clip('demo-stage',0,6,'<div class="demo-title">V4 · MOTION INSTRUMENTS</div>'+gauge('speed','VEHICLE SPEED',108,420,140,'km/h')+gauge('rpm','ENGINE RPM',548,420,8,'×1000')+'<section id="gap-panel" class="panel compact" style="left:108px;top:1030px;width:864px;height:204px"><div id="gap-rule" class="rule"></div><div class="label">PURSUER DISTANCE / WORLD POSITIONS</div><div id="gap-value" class="value">0</div><div class="unit">m</div><div class="track"><div id="gap-bar" class="fill"></div></div></section>')
demo+='</div>'+"""<script>(()=>{const C=HFComponents,V=V4Components,tl=gsap.timeline({paused:true}),speed=new C.SpeedometerOverlay({value:'#speed-value',needle:'#speed-needle',bar:'#speed-bar'}),rpm=new V.TachometerOverlay('#rpm-value','#rpm-needle','#rpm-bar'),gap=new C.PursuitDistanceHUD('#gap-value','#gap-bar');['speed','rpm','gap'].forEach((id,i)=>{new C.CinematicHUDPanel('#'+id+'-panel').animate(tl,.08+i*.10,6);new V.AnimatedTransition('#'+id+'-rule').animate(tl,.08+i*.10,6);});const p={t:0};function draw(t){const s=C.vehicleAt(t*2.5);speed.render(s);rpm.render(s);gap.render(s);}tl.to(p,{t:6,duration:6,ease:'none',onUpdate:()=>draw(p.t)},0);window.addEventListener('hf-seek',e=>draw(e.detail.time));draw(0);window.__timelines=window.__timelines||{};window.__timelines.demo=tl;})();</script></body></html>"""
# Keep the demo editable as a root plus one documented sub-composition.
import re
inner=re.search(r'<div id="demo-stage" class="clip" data-start="0" data-duration="6">(.*)</div></div><script>',demo,re.S).group(1)
demo_js=demo.rsplit('<script>',1)[1].split('</script>')[0]
(D/'compositions').mkdir(exist_ok=True)
demo_css=CSS.split('.caption{')[0]+'.demo-title{position:absolute;left:108px;top:190px;font-size:38px;font-weight:700;letter-spacing:1px}'
(D/'compositions/demo.html').write_text(template('demo',inner,demo_js).replace(CSS,demo_css))
(D/'index.html').write_text(HEAD+'''<div id="root" data-composition-id="demo-main" data-start="0" data-duration="6" data-width="1080" data-height="1920" data-fps="30"><div id="demo" class="clip" data-composition-id="demo" data-composition-src="compositions/demo.html" data-start="0" data-duration="6" data-track-index="0" data-track-kind="graphics" data-width="1080" data-height="1920"></div></div><script>const tl=gsap.timeline({paused:true});tl.to({t:0},{t:6,duration:6,ease:'none'});window.__timelines=window.__timelines||{};window.__timelines['demo-main']=tl;</script></body></html>''')
(H/'index.motion.json').write_text(json.dumps({'duration':15,'assertions':[{'kind':'appearsBy','selector':'#clock-panel','bySec':.35},{'kind':'staysInFrame','selector':'#speed-panel'},{'kind':'staysInFrame','selector':'#rpm-panel'},{'kind':'staysInFrame','selector':'#gap-panel'}]},indent=2))
shutil.copy2(R/'audio/MIX_MASTER.wav',H/'assets/mix.wav')
print('V4 actual HyperFrames composition + speed/RPM + transitions + measured phrase captions generated')
